1	/**
2	 * T7 — End-to-end browser QA and regression coverage
3	 *
4	 * Verifies the full workspace-tabs-data-flow integration:
5	 *   - Browser-local workspace summary lifecycle and import flow
6	 *   - Workspace switching and context updates
7	 *   - Sidebar independent active-task query (not derived from other payloads)
8	 *   - Manual sync and stale-source handling
9	 *   - Tab management: open/focus/close for task tabs and feature tabs
10	 *   - Board surface routing: board, task-tab, feature-tab
11	 *   - No GitHub direct workspace-data reads in the new workspace flow
12	 *   - Structured error codes mapped to UI error states
13	 *   - Import modal error handling for each validation code
14	 *   - Query param contract: sidebar vs task-mode vs feature-mode
15	 *   - SIDEBAR_TASK_PARAMS independence from other query builders
16	 */
17	
18	import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
19	import React from "react";
20	import { renderToStaticMarkup } from "react-dom/server";
21	
22	// ─── localStorage shim ────────────────────────────────────────────────────────
23	
24	const lsStore: Record<string, string> = {};
25	const mockLS = {
26	  getItem: (k: string) => lsStore[k] ?? null,
27	  setItem: (k: string, v: string) => { lsStore[k] = v; },
28	  removeItem: (k: string) => { delete lsStore[k]; },
29	  clear: () => { for (const k of Object.keys(lsStore)) delete lsStore[k]; },
30	};
31	// @ts-expect-error test shim
32	global.window = {};
33	// @ts-expect-error test shim
34	global.localStorage = mockLS;
35	
36	import {
37	  getLocalWorkspaceSummaries,
38	  saveLocalWorkspaceSummary,
39	  removeLocalWorkspaceSummary,
40	  getSelectedWorkspaceId,
41	  setSelectedWorkspaceId,
42	  clearSelectedWorkspaceId,
43	  resolveBootstrapWorkspaceId,
44	} from "../services/local-workspace-store";
45	
46	import {
47	  buildFeatureParams,
48	  buildTaskParams,
49	  SIDEBAR_TASK_PARAMS,
50	} from "../services/workflow-backend/query-params";
51	
52	import {
53	  adaptWorkspaceDetail,
54	  adaptTaskSummariesToFeatures,
55	  adaptTaskSummary,
56	  adaptFeatureSummary,
57	  buildImportLocalSummary,
58	} from "../features/workspaces/lib/workspaceAdapter";
59	
60	import type {
61	  LocalWorkspaceSummary,
62	  WorkspaceDetail,
63	  FeatureSummary,
64	  TaskSummary,
65	  ApiError,
66	  ImportWorkspaceRequest,
67	} from "../services/workflow-backend/types";
68	
69	// ─── Fixtures ─────────────────────────────────────────────────────────────────
70	
71	function makeLocalSummary(partial: Partial<LocalWorkspaceSummary> = {}): LocalWorkspaceSummary {
72	  return {
73	    workspaceId: "ws-uuid-001",
74	    name: "My Workspace",
75	    repo_url: "https://github.com/org/repo",
76	    default_branch: "main",
77	    last_opened_at: "2026-01-01T00:00:00Z",
78	    ...partial,
79	  };
80	}
81	
82	function makeFeatureSummary(partial: Partial<FeatureSummary> = {}): FeatureSummary {
83	  return {
84	    id: "feat-uuid-1",
85	    feature_id: "my-feature",
86	    feature_name: "my-feature",
87	    title: "My Feature",
88	    status: "in_implementation",
89	    current_stage: "in_implementation",
90	    updated_at: "2026-01-01T00:00:00Z",
91	    task_counts: { total: 2, done: 1, in_progress: 1, blocked: 0, ready: 0, todo: 0 },
92	    ...partial,
93	  };
94	}
95	
96	function makeTaskSummary(partial: Partial<TaskSummary> = {}): TaskSummary {
97	  return {
98	    id: "task-uuid-1",
99	    task_id: "T1",
100	    task_name: "T1",
101	    feature_id: "feat-uuid-1",
102	    feature_name: "my-feature",
103	    title: "Implement API client",
104	    status: "in_progress",
105	    repo: "digital-factory-ui",
106	    branch: "feature/my-feature-T1",
107	    is_blocked: false,
108	    pr: null,
109	    workspace_pr: null,
110	    ...partial,
111	  };
112	}
113	
114	function makeWorkspaceDetail(partial: Partial<WorkspaceDetail> = {}): WorkspaceDetail {
115	  return {
116	    id: "ws-uuid-001",
117	    name: "My Workspace",
118	    slug: "my-workspace",
119	    repo_url: "https://github.com/org/repo",
120	    source_state: { stale: false },
121	    updated_at: "2026-01-01T00:00:00Z",
122	    features: [],
123	    tasks: [],
124	    ...partial,
125	  };
126	}
127	
128	beforeEach(() => {
129	  mockLS.clear();
130	});
131	
132	// ─── Section 1: Browser-local workspace summary lifecycle ─────────────────────
133	
134	describe("browser-local workspace summary: privacy and isolation", () => {
135	  it("starts empty — no workspace shown until one is imported", () => {
136	    expect(getLocalWorkspaceSummaries()).toEqual([]);
137	    expect(getSelectedWorkspaceId()).toBeNull();
138	  });
139	
140	  it("stores only picker metadata — not features, tasks, or full WorkspaceDetail", () => {
141	    const summary = makeLocalSummary();
142	    saveLocalWorkspaceSummary(summary);
143	    const stored = getLocalWorkspaceSummaries();
144	    expect(stored).toHaveLength(1);
145	    const keys = Object.keys(stored[0]);
146	    // Only picker metadata keys are allowed
147	    expect(keys).toEqual(expect.arrayContaining(["workspaceId", "name", "repo_url", "default_branch", "last_opened_at"]));
148	    // No full workspace data keys
149	    expect(keys).not.toContain("features");
150	    expect(keys).not.toContain("tasks");
151	    expect(keys).not.toContain("source_state");
152	    expect(keys).not.toContain("slug");
153	  });
154	
155	  it("workspace imported by one profile is not shown in another because summaries are browser-local", () => {
156	    // Simulate profile A: save a summary
157	    saveLocalWorkspaceSummary(makeLocalSummary({ workspaceId: "ws-profile-a", name: "Profile A WS" }));
158	    expect(getLocalWorkspaceSummaries()).toHaveLength(1);
159	
160	    // Simulate profile B: clear localStorage (different browser profile)
161	    mockLS.clear();
162	    // Profile B sees no workspaces — backend-only workspaces not visible
163	    expect(getLocalWorkspaceSummaries()).toHaveLength(0);
164	  });
165	
166	  it("removing a local summary does not delete from backend — only from the local picker", () => {
167	    saveLocalWorkspaceSummary(makeLocalSummary({ workspaceId: "ws-a" }));
168	    saveLocalWorkspaceSummary(makeLocalSummary({ workspaceId: "ws-b" }));
169	    removeLocalWorkspaceSummary("ws-a");
170	    // ws-a removed from local picker only
171	    expect(getLocalWorkspaceSummaries()).toHaveLength(1);
172	    expect(getLocalWorkspaceSummaries()[0].workspaceId).toBe("ws-b");
173	    // ws-b still present
174	  });
175	
176	  it("saving same workspaceId twice upserts (no duplicates)", () => {
177	    saveLocalWorkspaceSummary(makeLocalSummary({ workspaceId: "ws-a", name: "Old" }));
178	    saveLocalWorkspaceSummary(makeLocalSummary({ workspaceId: "ws-a", name: "New" }));
179	    const list = getLocalWorkspaceSummaries();
180	    expect(list).toHaveLength(1);
181	    expect(list[0].name).toBe("New");
182	  });
183	
184	  it("malformed localStorage value returns empty list instead of throwing", () => {
185	    lsStore["dashboard:workspace-summaries"] = "{corrupt:json{{";
186	    expect(() => getLocalWorkspaceSummaries()).not.toThrow();
187	    expect(getLocalWorkspaceSummaries()).toEqual([]);
188	  });
189	});
190	
191	// ─── Section 2: Bootstrap workspace ID selection ──────────────────────────────
192	
193	describe("bootstrap workspace ID resolution", () => {
194	  it("returns null with no summaries and no stored ID", () => {
195	    expect(resolveBootstrapWorkspaceId([], null)).toBeNull();
196	  });
197	
198	  it("prefers stored ID over most-recently-opened heuristic", () => {
199	    const summaries = [
200	      makeLocalSummary({ workspaceId: "ws-recent", last_opened_at: "2026-06-01T00:00:00Z" }),
201	      makeLocalSummary({ workspaceId: "ws-stored", last_opened_at: "2026-01-01T00:00:00Z" }),
202	    ];
203	    expect(resolveBootstrapWorkspaceId(summaries, "ws-stored")).toBe("ws-stored");
204	  });
205	
206	  it("picks most recently opened when stored ID is null", () => {
207	    const summaries = [
208	      makeLocalSummary({ workspaceId: "ws-old", last_opened_at: "2025-01-01T00:00:00Z" }),
209	      makeLocalSummary({ workspaceId: "ws-new", last_opened_at: "2026-06-01T00:00:00Z" }),
210	    ];
211	    expect(resolveBootstrapWorkspaceId(summaries, null)).toBe("ws-new");
212	  });
213	
214	  it("does not mutate the input summaries array during sort", () => {
215	    const summaries = [
216	      makeLocalSummary({ workspaceId: "ws-a", last_opened_at: "2025-01-01T00:00:00Z" }),
217	      makeLocalSummary({ workspaceId: "ws-b", last_opened_at: "2026-06-01T00:00:00Z" }),
218	    ];
219	    const originalOrder = summaries.map((s) => s.workspaceId);
220	    resolveBootstrapWorkspaceId(summaries, null);
221	    expect(summaries.map((s) => s.workspaceId)).toEqual(originalOrder);
222	  });
223	
224	  it("returns the only summary when exactly one exists", () => {
225	    const summaries = [makeLocalSummary({ workspaceId: "ws-only" })];
226	    expect(resolveBootstrapWorkspaceId(summaries, null)).toBe("ws-only");
227	  });
228	});
229	
230	// ─── Section 3: Selected workspace ID persistence ─────────────────────────────
231	
232	describe("selected workspace ID persistence", () => {
233	  it("returns null before any selection", () => {
234	    expect(getSelectedWorkspaceId()).toBeNull();
235	  });
236	
237	  it("persists and retrieves the selected workspace ID", () => {
238	    setSelectedWorkspaceId("ws-123");
239	    expect(getSelectedWorkspaceId()).toBe("ws-123");
240	  });
241	
242	  it("replaces previous selection on switch", () => {
243	    setSelectedWorkspaceId("ws-a");
244	    setSelectedWorkspaceId("ws-b");
245	    expect(getSelectedWorkspaceId()).toBe("ws-b");
246	  });
247	
248	  it("clears the selection", () => {
249	    setSelectedWorkspaceId("ws-a");
250	    clearSelectedWorkspaceId();
251	    expect(getSelectedWorkspaceId()).toBeNull();
252	  });
253	
254	  it("workspace switch: setSelectedWorkspaceId + saveLocalWorkspaceSummary together", () => {
255	    saveLocalWorkspaceSummary(makeLocalSummary({ workspaceId: "ws-x", last_opened_at: "2026-01-01T00:00:00Z" }));
256	    saveLocalWorkspaceSummary(makeLocalSummary({ workspaceId: "ws-y", last_opened_at: "2026-01-01T00:00:00Z" }));
257	    setSelectedWorkspaceId("ws-y");
258	    expect(resolveBootstrapWorkspaceId(getLocalWorkspaceSummaries(), getSelectedWorkspaceId())).toBe("ws-y");
259	  });
260	});
261	
262	// ─── Section 4: Import local summary builder ──────────────────────────────────
263	
264	describe("buildImportLocalSummary — import flow", () => {
265	  const now = "2026-05-21T12:00:00.000Z";
266	
267	  it("sets workspaceId from WorkspaceDetail.id", () => {
268	    const detail = makeWorkspaceDetail({ id: "ws-imported-1" });
269	    const body: ImportWorkspaceRequest = { repo_url: "https://github.com/org/repo" };
270	    expect(buildImportLocalSummary(detail, body, now).workspaceId).toBe("ws-imported-1");
271	  });
272	
273	  it("prefers detail.name over body.name", () => {
274	    const detail = makeWorkspaceDetail({ name: "Backend Name" });
275	    const body: ImportWorkspaceRequest = { repo_url: "https://github.com/org/repo", name: "Body Name" };
276	    expect(buildImportLocalSummary(detail, body, now).name).toBe("Backend Name");
277	  });
278	
279	  it("falls back to body.name when detail.name is empty", () => {
280	    const detail = makeWorkspaceDetail({ name: "" });
281	    const body: ImportWorkspaceRequest = { repo_url: "https://github.com/org/repo", name: "Body Name" };
282	    expect(buildImportLocalSummary(detail, body, now).name).toBe("Body Name");
283	  });
284	
285	  it("falls back to repo basename when no name is available", () => {
286	    const detail = makeWorkspaceDetail({ name: "" });
287	    const body: ImportWorkspaceRequest = { repo_url: "https://github.com/org/my-repo" };
288	    expect(buildImportLocalSummary(detail, body, now).name).toBe("my-repo");
289	  });
290	
291	  it("strips .git suffix from repo basename", () => {
292	    const detail = makeWorkspaceDetail({ name: "" });
293	    const body: ImportWorkspaceRequest = { repo_url: "https://github.com/org/my-repo.git" };
294	    expect(buildImportLocalSummary(detail, body, now).name).toBe("my-repo");
295	  });
296	
297	  it("defaults default_branch to main when not provided", () => {
298	    const detail = makeWorkspaceDetail();
299	    const body: ImportWorkspaceRequest = { repo_url: "https://github.com/org/repo" };
300	    expect(buildImportLocalSummary(detail, body, now).default_branch).toBe("main");
301	  });
302	
303	  it("uses body.default_branch when provided", () => {
304	    const detail = makeWorkspaceDetail();
305	    const body: ImportWorkspaceRequest = { repo_url: "https://github.com/org/repo", default_branch: "dev" };
306	    expect(buildImportLocalSummary(detail, body, now).default_branch).toBe("dev");
307	  });
308	
309	  it("sets last_opened_at from the now parameter", () => {
310	    const detail = makeWorkspaceDetail();
311	    const body: ImportWorkspaceRequest = { repo_url: "https://github.com/org/repo" };
312	    expect(buildImportLocalSummary(detail, body, now).last_opened_at).toBe(now);
313	  });
314	
315	  it("stores repo_url from request body", () => {
316	    const detail = makeWorkspaceDetail();
317	    const body: ImportWorkspaceRequest = { repo_url: "https://github.com/org/my-repo" };
318	    expect(buildImportLocalSummary(detail, body, now).repo_url).toBe("https://github.com/org/my-repo");
319	  });
320	
321	  it("full import flow: build summary → save → select → retrieve", () => {
322	    const detail = makeWorkspaceDetail({ id: "ws-flow-1", name: "Flow WS" });
323	    const body: ImportWorkspaceRequest = { repo_url: "https://github.com/org/repo" };
324	    const summary = buildImportLocalSummary(detail, body, now);
325	    saveLocalWorkspaceSummary(summary);
326	    setSelectedWorkspaceId(summary.workspaceId);
327	    expect(getLocalWorkspaceSummaries()).toHaveLength(1);
328	    expect(getSelectedWorkspaceId()).toBe("ws-flow-1");
329	    expect(resolveBootstrapWorkspaceId(getLocalWorkspaceSummaries(), getSelectedWorkspaceId())).toBe("ws-flow-1");
330	  });
331	});
332	
333	// ─── Section 5: Sidebar active-task query independence ────────────────────────
334	
335	describe("SIDEBAR_TASK_PARAMS — independent from other query builders", () => {
336	  it("uses exactly the documented active statuses", () => {
337	    expect(SIDEBAR_TASK_PARAMS.get("status")).toBe("in_progress,in_review,ready");
338	  });
339	
340	  it("uses task_id_asc sort", () => {
341	    expect(SIDEBAR_TASK_PARAMS.get("sort")).toBe("task_id_asc");
342	  });
343	
344	  it("always fetches page 1 with limit 50", () => {
345	    expect(SIDEBAR_TASK_PARAMS.get("page")).toBe("1");
346	    expect(SIDEBAR_TASK_PARAMS.get("limit")).toBe("50");
347	  });
348	
349	  it("does not include task search fields (task_id, title, repo)", () => {
350	    expect(SIDEBAR_TASK_PARAMS.has("task_id")).toBe(false);
351	    expect(SIDEBAR_TASK_PARAMS.has("title")).toBe(false);
352	    expect(SIDEBAR_TASK_PARAMS.has("repo")).toBe(false);
353	  });
354	
355	  it("sidebar params differ from a task-mode search with the same status filter", () => {
356	    const taskModeParams = buildTaskParams({
357	      status: ["in_progress", "in_review", "ready"],
358	      sort: "task_id_asc",
359	      page: 1,
360	      limit: 20,
361	    });
362	    // limit is 50 for sidebar vs 20 for task-mode
363	    expect(SIDEBAR_TASK_PARAMS.get("limit")).toBe("50");
364	    expect(taskModeParams.get("limit")).toBe("20");
365	  });
366	
367	  it("SIDEBAR_TASK_PARAMS is a stable constant (frozen URLSearchParams)", () => {
368	    // Mutating should not affect the constant
369	    const copy = new URLSearchParams(SIDEBAR_TASK_PARAMS);
370	    copy.set("title", "injected");
371	    expect(SIDEBAR_TASK_PARAMS.has("title")).toBe(false);
372	  });
373	});
374	
375	// ─── Section 6: Board-level workspace adapter ─────────────────────────────────
376	
377	describe("adaptWorkspaceDetail — board data adapter", () => {
378	  it("returns empty array for a workspace with no features", () => {
379	    const detail = makeWorkspaceDetail({ features: [], tasks: [] });
380	    expect(adaptWorkspaceDetail(detail)).toEqual([]);
381	  });
382	
383	  it("produces one ParsedFeature per FeatureSummary", () => {
384	    const features = [
385	      makeFeatureSummary({ id: "f1", feature_name: "feat-a" }),
386	      makeFeatureSummary({ id: "f2", feature_name: "feat-b" }),
387	    ];
388	    const result = adaptWorkspaceDetail(makeWorkspaceDetail({ features, tasks: [] }));
389	    expect(result).toHaveLength(2);
390	  });
391	
392	  it("uses feature_name as the ParsedFeature.id", () => {
393	    const features = [makeFeatureSummary({ feature_name: "my-feature" })];
394	    const result = adaptWorkspaceDetail(makeWorkspaceDetail({ features, tasks: [] }));
395	    expect(result[0].id).toBe("my-feature");
396	  });
397	
398	  it("routes tasks to their owning feature by feature_id UUID", () => {
399	    const features = [
400	      makeFeatureSummary({ id: "f-uuid-1", feature_name: "feat-a" }),
401	      makeFeatureSummary({ id: "f-uuid-2", feature_name: "feat-b" }),
402	    ];
403	    const tasks = [
404	      makeTaskSummary({ task_name: "T1", feature_id: "f-uuid-1" }),
405	      makeTaskSummary({ task_name: "T2", feature_id: "f-uuid-2" }),
406	      makeTaskSummary({ task_name: "T3", feature_id: "f-uuid-1" }),
407	    ];
408	    const result = adaptWorkspaceDetail(makeWorkspaceDetail({ features, tasks }));
409	    const featA = result.find((f) => f.id === "feat-a")!;
410	    const featB = result.find((f) => f.id === "feat-b")!;
411	    expect(featA.tasks).toHaveLength(2);
412	    expect(featB.tasks).toHaveLength(1);
413	  });
414	
415	  it("tasks with unknown feature_id are excluded", () => {
416	    const features = [makeFeatureSummary({ id: "f-uuid-1", feature_name: "feat-a" })];
417	    const tasks = [
418	      makeTaskSummary({ task_name: "T1", feature_id: "f-uuid-1" }),
419	      makeTaskSummary({ task_name: "T9", feature_id: "f-uuid-orphan" }),
420	    ];
421	    const result = adaptWorkspaceDetail(makeWorkspaceDetail({ features, tasks }));
422	    expect(result[0].tasks).toHaveLength(1);
423	    expect(result[0].tasks[0].id).toBe("T1");
424	  });
425	});
426	
427	// ─── Section 7: Sidebar task adapter (adaptTaskSummariesToFeatures) ───────────
428	
429	describe("adaptTaskSummariesToFeatures — sidebar adapter", () => {
430	  it("groups tasks by feature_id (primary key)", () => {
431	    const tasks = [
432	      makeTaskSummary({ feature_id: "feat-uuid-a", feature_name: "feat-a", task_name: "T1" }),
433	      makeTaskSummary({ feature_id: "feat-uuid-a", feature_name: "feat-a", task_name: "T2" }),
434	      makeTaskSummary({ feature_id: "feat-uuid-b", feature_name: "feat-b", task_name: "T3" }),
435	    ];
436	    const result = adaptTaskSummariesToFeatures(tasks);
437	    expect(result).toHaveLength(2);
438	    const featA = result.find((f) => f.id === "feat-a")!;
439	    const featB = result.find((f) => f.id === "feat-b")!;
440	    expect(featA.tasks).toHaveLength(2);
441	    expect(featB.tasks).toHaveLength(1);
442	  });
443	
444	  it("returns empty array for empty input", () => {
445	    expect(adaptTaskSummariesToFeatures([])).toEqual([]);
446	  });
447	
448	  it("maps task_name to ParsedTask.id", () => {
449	    const tasks = [makeTaskSummary({ feature_id: "feat-uuid-a", feature_name: "feat-a", task_name: "T7" })];
450	    const result = adaptTaskSummariesToFeatures(tasks);
451	    expect(result[0].tasks[0].id).toBe("T7");
452	  });
453	
454	  it("maps is_blocked to blockedReason", () => {
455	    const tasks = [makeTaskSummary({ feature_id: "feat-uuid-a", feature_name: "feat-a", task_name: "T1", is_blocked: true })];
456	    const result = adaptTaskSummariesToFeatures(tasks);
457	    expect(result[0].tasks[0].blockedReason).toBe("blocked");
458	  });
459	
460	  it("sidebar result is independent from workspace detail result", () => {
461	    const workspaceTasks = [makeTaskSummary({ feature_id: "f-ws", feature_name: "feat-ws", task_name: "T1" })];
462	    const sidebarTasks = [
463	      makeTaskSummary({ feature_id: "f-sidebar", feature_name: "feat-sidebar", task_name: "T1", status: "in_progress" }),
464	    ];
465	    const wsResult = adaptTaskSummariesToFeatures(workspaceTasks);
466	    const sbResult = adaptTaskSummariesToFeatures(sidebarTasks);
467	    expect(wsResult[0].id).toBe("feat-ws");
468	    expect(sbResult[0].id).toBe("feat-sidebar");
469	  });
470	});
471	
472	// ─── Section 8: Query param contracts ─────────────────────────────────────────
473	
474	describe("query param contracts — feature search vs task search vs sidebar", () => {
475	  it("feature title search uses 'title' param", () => {
476	    const sp = buildFeatureParams({ title: "data" });
477	    expect(sp.get("title")).toBe("data");
478	    expect(sp.has("task_id")).toBe(false);
479	  });
480	
481	  it("task name search uses 'task_id' param (not 'name' or 'id')", () => {
482	    const sp = buildTaskParams({ task_id: "T1" });
483	    expect(sp.get("task_id")).toBe("T1");
484	    expect(sp.has("name")).toBe(false);
485	    expect(sp.has("id")).toBe(false);
486	  });
487	
488	  it("task title search uses 'title' param", () => {
489	    const sp = buildTaskParams({ title: "implement" });
490	    expect(sp.get("title")).toBe("implement");
491	  });
492	
493	  it("status filters are comma-separated for both feature and task", () => {
494	    const fSp = buildFeatureParams({ status: ["in_design", "in_implementation"] });
495	    const tSp = buildTaskParams({ status: ["in_progress", "in_review"] });
496	    expect(fSp.get("status")).toBe("in_design,in_implementation");
497	    expect(tSp.get("status")).toBe("in_progress,in_review");
498	  });
499	
500	  it("natural task order uses 'task_id_asc' sort", () => {
501	    const sp = buildTaskParams({ sort: "task_id_asc" });
502	    expect(sp.get("sort")).toBe("task_id_asc");
503	  });
504	
505	  it("feature search uses 'title_asc' sort", () => {
506	    const sp = buildFeatureParams({ sort: "title_asc" });
507	    expect(sp.get("sort")).toBe("title_asc");
508	  });
509	
510	  it("omits undefined fields from task params", () => {
511	    const sp = buildTaskParams({ task_id: "T2" });
512	    expect(sp.has("title")).toBe(false);
513	    expect(sp.has("status")).toBe(false);
514	    expect(sp.has("repo")).toBe(false);
515	    expect(sp.has("sort")).toBe(false);
516	  });
517	
518	  it("omits undefined fields from feature params", () => {
519	    const sp = buildFeatureParams({ title: "test" });
520	    expect(sp.has("status")).toBe(false);
521	    expect(sp.has("sort")).toBe(false);
