528	
529	describe("Import modal — structured error code mapping", () => {
530	  // Verify the error-mapping logic matches expected behavior from the spec
531	  type FieldError = { field?: "repo_url" | "name"; message: string };
532	
533	  function getErrorMessage(err: ApiError): FieldError {
534	    switch (err.code) {
535	      case "VALIDATION_INVALID_URL":
536	        return { field: "repo_url", message: "Invalid repository URL." };
537	      case "VALIDATION_MISSING_INPUT":
538	        return { field: "repo_url", message: err.message || "Repository URL is required." };
539	      case "GITHUB_NOT_FOUND":
540	        return { message: "Repository not found. Check the URL and try again." };
541	      case "GITHUB_UNAUTHORIZED":
542	        return { message: "GitHub access denied. Check repository permissions." };
543	      case "GITHUB_RATE_LIMIT":
544	        return { message: "GitHub rate limit reached. Please wait and try again." };
545	      case "ADAPTER_TIMEOUT":
546	        return { message: "Request timed out. Please try again." };
547	      default:
548	        return { message: err.message || "Import failed. Please try again." };
549	    }
550	  }
